const items = $input.all();

return items.map((item) => {
  const canonicalItems = $("Normalize Task").all();

const currentId =
  item.json.handoff_id ??
  item.json["Handoff ID"];

const canonicalItem = canonicalItems.find((candidate) => {
  const candidateId =
    candidate.json.handoff_id ??
    candidate.json["Handoff ID"];

  return candidateId === currentId;
});

const t = {
  ...(canonicalItem?.json ?? {}),
  ...item.json
};

item.json = t;

  const upper = (value) =>
    String(value ?? '').trim().toUpperCase();

  const lower = (value) =>
    String(value ?? '').trim().toLowerCase();

  const policy = upper(t.model_policy || 'AUTO');

  let selectedModel = '';
  let selectionReason = '';
  let fableRecommended = false;
  let fableReason = '';

  // ==================================================
  // 1. MANUAL MODEL OVERRIDE
  // ==================================================

  if (policy === 'SONNET') {
    selectedModel = 'claude-sonnet-5';
    selectionReason = 'Manual policy override: SONNET';
  } else if (policy === 'OPUS') {
    selectedModel = 'claude-opus-4-8';
    selectionReason = 'Manual policy override: OPUS';
  } else if (policy === 'FABLE') {
    selectedModel = 'claude-fable-5';
    selectionReason = 'Manual policy override: FABLE';
  } else {

    // ==================================================
    // 2. AUTO ROUTING: OPUS TRIGGERS
    // ==================================================

    const routingTaskType =
      t.routing_task_type ??
      t.task_type;

    const opusTriggers = [
      upper(t.quality_priority) === 'CRITICAL',

      upper(t.flagship_output) === 'TRUE',

      upper(t.complexity) === 'EXTREME',

      (
        upper(t.complexity) === 'HIGH' &&
        upper(t.ambiguity) === 'HIGH'
      ),

      upper(t.autonomy_required) === 'HIGH',

      [
        'cross_system_architecture',
        'multi_module_coding',
        'difficult_debugging',
        'large_refactor'
      ].includes(lower(routingTaskType)),

      (
        lower(routingTaskType) === 'reconciliation' &&
        upper(t.conflict_type) === 'INTERACTING'
      ),

      (
        upper(t.business_value) === 'CRITICAL' &&
        upper(t.novelty) === 'HIGH' &&
        upper(t.template_exists) === 'FALSE'
      ),

      (
        lower(t.last_model).includes('sonnet') &&
        upper(t.last_failure_type) === 'SUBSTANTIVE'
      )
    ];

    if (opusTriggers.some(Boolean)) {
      selectedModel = 'claude-opus-4-8';
      selectionReason =
        'AUTO: quality-first Opus trigger matched';
    } else {
      selectedModel = 'claude-sonnet-5';
      selectionReason =
        'AUTO: default production route';
    }

    // ==================================================
    // 3. FABLE RECOMMENDATION GATE
    // ==================================================

    const fableTriggers = [
      (
        upper(t.long_horizon) === 'TRUE' &&
        upper(t.complexity) === 'EXTREME'
      ),

      upper(t.interdependence) === 'EXTREME',

      (
        lower(t.last_model).includes('opus') &&
        upper(t.last_failure_type) === 'SUBSTANTIVE'
      )
    ];

    if (fableTriggers.some(Boolean)) {
      fableRecommended = true;
      fableReason =
        'Extreme or materially unresolved task; Max approval required before Fable use';
    }
  }

  // ==================================================
  // 4. WRITE ROUTING RESULT
  // ==================================================

  item.json.selected_model = selectedModel;
  item.json.selection_reason = selectionReason;

  item.json.fable_recommended =
    fableRecommended ? 'TRUE' : 'FALSE';

  item.json.fable_recommendation_reason =
    fableReason;

  item.json.Status =
    fableRecommended
      ? 'MAX_APPROVAL_REQUIRED'
      : 'ROUTED';

  return item;
});

const parseNonNegativeFinite = (raw, missingReason, invalidReason, negativeReason) => {
  if (
    raw === undefined ||
    raw === null ||
    (typeof raw === "string" && raw.trim() === "")
  ) {
    return { ok: false, value: null, reason: missingReason };
  }

  if (typeof raw === "boolean") {
    return { ok: false, value: null, reason: invalidReason };
  }

  const value = typeof raw === "number"
    ? raw
    : Number(String(raw).trim());

  if (!Number.isFinite(value)) {
    return { ok: false, value: null, reason: invalidReason };
  }

  if (value < 0) {
    return { ok: false, value: null, reason: negativeReason };
  }

  return {
    ok: true,
    value: Object.is(value, -0) ? 0 : value,
    reason: null
  };
};

const parseOptionalActual = (raw) => {
  if (
    raw === undefined ||
    raw === null ||
    (typeof raw === "string" && raw.trim() === "")
  ) {
    return { ok: true, known: false, value: null, reason: null };
  }

  const parsed = parseNonNegativeFinite(
    raw,
    "ACTUAL_COST_UNAVAILABLE",
    "ACTUAL_COST_INVALID",
    "ACTUAL_COST_NEGATIVE"
  );

  return {
    ok: parsed.ok,
    known: parsed.ok,
    value: parsed.value,
    reason: parsed.reason
  };
};

return $input.all().map((item) => {
  const t = item.json;
  const handoffId = String(
    t.handoff_id ?? t["Handoff ID"] ?? ""
  ).trim();
  const marker = handoffId ? `[handoff_id=${handoffId}] ` : "";

  const budget = parseNonNegativeFinite(
    t.api_cost_budget,
    "BUDGET_UNAVAILABLE",
    "BUDGET_INVALID",
    "BUDGET_NEGATIVE"
  );
  const estimate = parseNonNegativeFinite(
    t.estimated_cost_next_call,
    "COST_ESTIMATE_UNAVAILABLE",
    "COST_ESTIMATE_INVALID",
    "COST_ESTIMATE_NEGATIVE"
  );
  const actual = parseOptionalActual(t.actual_cost_total);

  let budgetApproved = false;
  let reason = null;
  let detail = null;
  let projectedTotal = null;
  let remainingBudget = null;

  if (!budget.ok) {
    reason = budget.reason;
    detail = `${marker}${reason}: api_cost_budget is unavailable or invalid`;
  } else if (!estimate.ok) {
    reason = estimate.reason;
    detail = `${marker}${reason}: estimated_cost_next_call is unavailable or invalid`;
  } else if (!actual.ok) {
    reason = actual.reason;
    detail = `${marker}${reason}: actual_cost_total is invalid`;
  } else {
    const knownActualCost = actual.known ? actual.value : 0;
    projectedTotal = knownActualCost + estimate.value;
    remainingBudget = budget.value - knownActualCost;

    if (projectedTotal > budget.value) {
      reason = "BUDGET_EXCEEDED";
      detail =
        `${marker}BUDGET_EXCEEDED: projected total ${projectedTotal} exceeds budget ${budget.value}`;
    } else {
      budgetApproved = true;
      reason = "BUDGET_APPROVED";
      detail =
        `${marker}BUDGET_APPROVED: projected total ${projectedTotal} is within budget ${budget.value}`;
    }
  }

  t.projected_cost_total = projectedTotal;
  t.remaining_budget_before_call = remainingBudget;
  t.budget_approved = budgetApproved ? "TRUE" : "FALSE";
  t.budget_gate_reason = reason;
  t.budget_gate_detail = detail;

  if (!budgetApproved) {
    t.status = "BUDGET_BLOCKED";
    t.Status = "BUDGET_BLOCKED";
  }

  return item;
});

const originals = $("Normalize Task").all();
const budgets = $("Check Budget").all();

return $input.all().map((item) => {
  const routingUpdate = item.json;

  const currentId =
    routingUpdate.handoff_id ??
    routingUpdate["Handoff ID"];

  const original =
    originals.find((candidate) =>
      (candidate.json.handoff_id ?? candidate.json["Handoff ID"]) === currentId
    )?.json ?? {};

  const budget =
    budgets.find((candidate) =>
      (candidate.json.handoff_id ?? candidate.json["Handoff ID"]) === currentId
    )?.json ?? {};

  const handoffId =
    currentId ??
    original.handoff_id ??
    original["Handoff ID"] ??
    budget.handoff_id ??
    budget["Handoff ID"];

  if (!handoffId) {
    throw new Error("Missing required field: handoff_id");
  }

  return {
    json: {
      ...original,
      ...budget,
      ...routingUpdate,
      handoff_id: handoffId,
      status: "ROUTED",
      "Handoff ID": handoffId,
      "Status": "ROUTED"
    }
  };
});

const CANONICAL_TASK_TYPES = new Set([
  "VIDEO",
  "TEXT",
  "UNKNOWN"
]);

const ALLOWED_STATUSES = new Set([
  "NEW",
  "CLAIMED",
  "VALIDATING",
  "ROUTED",
  "RUNNING",
  "WAITING_HUMAN",
  "COMPLETED",
  "FAILED",
  "BUDGET_BLOCKED",
  "SAFETY_BLOCKED",
  "CANCELLED"
]);

const isBlank = (value) =>
  value === undefined ||
  value === null ||
  String(value).trim() === "";

const stringOrNull = (value) =>
  isBlank(value)
    ? null
    : String(value).trim();

const valueOrNull = (value) =>
  isBlank(value)
    ? null
    : value;

const numberOrNull = (value) => {
  if (isBlank(value)) {
    return null;
  }

  const number = Number(value);

  return Number.isFinite(number)
    ? number
    : null;
};

const isoOrNull = (value) => {
  if (isBlank(value)) {
    return null;
  }

  const date = new Date(value);

  return Number.isNaN(date.getTime())
    ? null
    : date.toISOString();
};

const processingStartedAt = new Date().toISOString();

const executionId =
  $execution?.id == null
    ? null
    : String($execution.id);

const canonicalOutputs = $input.all().map((item) => {
  const source = item.json;

  const warnings = Array.isArray(source.validation_warnings)
    ? [...source.validation_warnings]
    : [];

  const addWarning = (warning) => {
    if (!warnings.includes(warning)) {
      warnings.push(warning);
    }
  };

  const handoffId = stringOrNull(
    source.handoff_id ??
    source["Handoff ID"]
  );

  if (!handoffId) {
    throw new Error(
      "Canonical validation failed: missing handoff_id"
    );
  }

  const incomingSchemaVersion =
    stringOrNull(source.schema_version);

  const isLegacy =
    incomingSchemaVersion === null;

  if (
    !isLegacy &&
    incomingSchemaVersion !== "1.0"
  ) {
    throw new Error(
      `[handoff_id=${handoffId}] Canonical validation failed: unsupported schema_version ${incomingSchemaVersion}`
    );
  }

  const rawTaskType =
    stringOrNull(source.task_type);

  const normalizedRawTaskType =
    rawTaskType?.toUpperCase() ?? null;

  let taskType = null;

  if (
    normalizedRawTaskType &&
    CANONICAL_TASK_TYPES.has(normalizedRawTaskType)
  ) {
    taskType = normalizedRawTaskType;
  } else if (isLegacy) {
    taskType = "TEXT";
  } else if (rawTaskType !== null) {
    taskType = "UNKNOWN";
    addWarning(
      `INVALID_TASK_TYPE_NORMALIZED_TO_UNKNOWN:${rawTaskType}`
    );
  }

  const explicitRoutingTaskType =
    stringOrNull(source.routing_task_type);

  const routingTaskType =
    explicitRoutingTaskType ??
    (
      rawTaskType !== null &&
      !CANONICAL_TASK_TYPES.has(
        normalizedRawTaskType
      )
        ? rawTaskType
        : null
    );

  const clientId =
    stringOrNull(source.client_id);

  const projectId =
    stringOrNull(source.project_id);

  const taskDescription =
    stringOrNull(
      source.task_description ??
      source["Question / Task"]
    );

  const sourceRef =
    stringOrNull(
      source.source_ref ??
      source["Context / Source Link"]
    );

  const incomingCreatedAt =
    source.created_at ??
    source.Date;

  let createdAt =
    isoOrNull(incomingCreatedAt);

  if (isLegacy && createdAt === null) {
    if (!isBlank(incomingCreatedAt)) {
      addWarning(
        "INVALID_CREATED_AT_REPLACED"
      );
    } else {
      addWarning(
        "MISSING_CREATED_AT_GENERATED"
      );
    }

    createdAt = new Date().toISOString();
  }

  const rawStatus =
    stringOrNull(
      source.status ??
      source.Status
    );

  const status =
    rawStatus !== null
      ? rawStatus.toUpperCase()
      : isLegacy
        ? "NEW"
        : null;

  if (isLegacy) {
    if (clientId === null) {
      addWarning("MISSING_CLIENT_ID");
    }

    if (projectId === null) {
      addWarning("MISSING_PROJECT_ID");
    }

    if (taskDescription === null) {
      addWarning("MISSING_TASK_DESCRIPTION");
    }

    if (sourceRef === null) {
      addWarning("MISSING_SOURCE_REF");
    }
  }

  const schemaVersion = "1.0";
  const legacyCompatibility = isLegacy;

  if (!isLegacy) {
    const requiredFields = {
      handoff_id: handoffId,
      task_type: taskType,
      client_id: clientId,
      project_id: projectId,
      source_ref: sourceRef,
      task_description: taskDescription,

      status,
      created_at: createdAt,
      schema_version: incomingSchemaVersion
    };

    const missingFields = Object.entries(
      requiredFields
    )
      .filter(([, value]) => isBlank(value))
      .map(([field]) => field);

    if (missingFields.length > 0) {
      throw new Error(
        `[handoff_id=${handoffId}] Canonical validation failed: missing required fields: ${missingFields.join(", ")}`
      );
    }

    if (!ALLOWED_STATUSES.has(status)) {
      throw new Error(
        `[handoff_id=${handoffId}] Canonical validation failed: invalid status ${status}`
      );
    }
  }

  const apiCostBudget =
    numberOrNull(source.api_cost_budget);

  const estimatedCostNextCall =
    numberOrNull(
      source.estimated_cost_next_call
    );

  const parsedActualCostTotal =
    typeof source.actual_cost_total === "boolean"
      ? null
      : numberOrNull(source.actual_cost_total);

  const actualCostTotal =
    parsedActualCostTotal !== null &&
    parsedActualCostTotal >= 0
      ? (Object.is(parsedActualCostTotal, -0) ? 0 : parsedActualCostTotal)
      : null;

  const actualCostOpenAI = null;
  const actualCostClaude = null;
  const costStatus = "UNAVAILABLE";

  const isVideo =
    taskType === "VIDEO";

  return {
    json: {
      "Handoff ID": handoffId,
      handoff_id: handoffId,

      task_type: taskType,
      routing_task_type: routingTaskType,

      client_id: clientId,
      project_id: projectId,

      source_ref: sourceRef,
      task_description: taskDescription,

      deliverable_ref:
        stringOrNull(
          source.deliverable_ref ??
          source["Result Link"]
        ),

      status,
      created_at: createdAt,
      schema_version: schemaVersion,
      legacy_compatibility: legacyCompatibility,
      validation_warnings: warnings,

      execution_id: executionId,
      started_at: processingStartedAt,
      workflow_version: null,
      retry_count: null,

      question_task: taskDescription,
      context_source_link: sourceRef,

      required_output:
        stringOrNull(
          source.required_output ??
          source["Required Output"]
        ),

      area:
        stringOrNull(
          source.area ??
          source.Area
        ),

      from_ai:
        stringOrNull(
          source.from_ai ??
          source["From AI"]
        ),

      to_ai:
        stringOrNull(
          source.to_ai ??
          source["To AI"]
        ),

      model_policy:
        stringOrNull(source.model_policy),

      risk:
        stringOrNull(source.risk),

      complexity:
        stringOrNull(source.complexity),

      quality_priority:
        stringOrNull(source.quality_priority),

      flagship_output:
        valueOrNull(source.flagship_output),

      benchmark_required:
        valueOrNull(source.benchmark_required),

      ambiguity:
        stringOrNull(source.ambiguity),

      autonomy_required:
        stringOrNull(source.autonomy_required),

      conflict_type:
        stringOrNull(source.conflict_type),

      business_value:
        stringOrNull(source.business_value),

      novelty:
        stringOrNull(source.novelty),

      template_exists:
        valueOrNull(source.template_exists),

      last_model:
        stringOrNull(source.last_model),

      last_failure_type:
        stringOrNull(source.last_failure_type),

      long_horizon:
        valueOrNull(source.long_horizon),

      interdependence:
        stringOrNull(source.interdependence),

      api_cost_budget: apiCostBudget,
      estimated_cost_next_call:
        estimatedCostNextCall,

      actual_cost_total: actualCostTotal,
      actual_cost_openai: actualCostOpenAI,
      actual_cost_claude: actualCostClaude,

      currency:
        stringOrNull(source.currency),

      cost_status: costStatus,

      transcript_ref:
        isVideo
          ? stringOrNull(source.transcript_ref)
          : null,

      transcript_status:
        isVideo
          ? stringOrNull(source.transcript_status)
          : null,

      transcript_language:
        isVideo
          ? stringOrNull(source.transcript_language)
          : null,

      transcript_duration_seconds:
        isVideo
          ? numberOrNull(
              source.transcript_duration_seconds
            )
          : null,

      transcript_provider:
        isVideo
          ? stringOrNull(source.transcript_provider)
          : null,

      transcript_cost:
        isVideo
          ? numberOrNull(source.transcript_cost)
          : null,

      video_analysis_mode:
        isVideo
          ? stringOrNull(
              source.video_analysis_mode
            )
          : null
    }
  };
});

const canonicalIds = canonicalOutputs.map((item) =>
  String(
    item.json.handoff_id ??
    item.json["Handoff ID"] ??
    ""
  ).trim()
);

const seenCanonicalIds = new Set();
for (const handoffId of canonicalIds) {
  if (!handoffId) {
    throw new Error(
      "Canonical validation failed: missing handoff_id"
    );
  }
  if (seenCanonicalIds.has(handoffId)) {
    throw new Error(
      `[handoff_id=${handoffId}] Duplicate canonical handoff_id`
    );
  }
  seenCanonicalIds.add(handoffId);
}

return canonicalOutputs;

