parameters.jsCode:
const normalizeId = (value) => {
  if (value === undefined || value === null) return null;
  const id = String(value).trim();
  return id === "" ? null : id;
};

const uniqueIdMap = (items, label) => {
  const map = new Map();
  for (const item of items) {
    const id = normalizeId(
      item.json?.handoff_id ?? item.json?.["Handoff ID"]
    );
    if (!id) {
      throw new Error(`${label}: blank Handoff ID`);
    }
    if (map.has(id)) {
      throw new Error(`[handoff_id=${id}] ${label}: duplicate Handoff ID`);
    }
    map.set(id, item.json);
  }
  return map;
};

const openaiItems = $("Restore OpenAI Task ID").all();
const claudeItems = $("Restore Claude Task ID").all();
const mergedItems = $input.all();
const canonicals = $("Build AI Request").all();

const openaiMap = uniqueIdMap(openaiItems, "Compare AI Responses OpenAI set");
const claudeMap = uniqueIdMap(claudeItems, "Compare AI Responses Claude set");
const expectedIds = [...openaiMap.keys()];

if (
  expectedIds.length !== claudeMap.size ||
  expectedIds.some((id) => !claudeMap.has(id))
) {
  throw new Error("Compare AI Responses: OpenAI and Claude Handoff ID sets differ");
}

if (mergedItems.length !== expectedIds.length) {
  throw new Error(
    `Compare AI Responses: Combine Dual AI Responses cardinality ${mergedItems.length} does not equal expected ${expectedIds.length}`
  );
}

const mergedMap = uniqueIdMap(mergedItems, "Compare AI Responses Combine Dual AI Responses output");
if (
  mergedMap.size !== expectedIds.length ||
  expectedIds.some((id) => !mergedMap.has(id)) ||
  [...mergedMap.keys()].some((id) => !openaiMap.has(id))
) {
  throw new Error("Compare AI Responses: Combine Dual AI Responses output ID set differs from expected set");
}

return expectedIds.map((currentId) => {
  const merged = mergedMap.get(currentId);
  const openaiId = normalizeId(merged.openai_handoff_id);
  const claudeId = normalizeId(merged.claude_handoff_id);

  if (openaiId !== currentId || claudeId !== currentId) {
    throw new Error(
      `[handoff_id=${currentId}] Compare AI Responses: provider Handoff ID mismatch`
    );
  }

  const canonicalMatches = canonicals.filter((candidate) =>
    normalizeId(
      candidate.json?.handoff_id ??
      candidate.json?.["Handoff ID"]
    ) === currentId
  );
  if (canonicalMatches.length !== 1) {
    throw new Error(
      `[handoff_id=${currentId}] Compare AI Responses: expected exactly one canonical match, found ${canonicalMatches.length}`
    );
  }
  const canonical = canonicalMatches[0].json;

  const openaiRaw = merged.openai_raw ?? {};
  const claudeRaw = merged.claude_raw ?? {};
  const openaiMessage =
    openaiRaw.output?.find((entry) => entry?.type === "message") ??
    openaiRaw.output?.find((entry) => Array.isArray(entry?.content)) ??
    null;
  const openaiResponse =
    openaiMessage?.content?.find((entry) => typeof entry?.text === "string")?.text ??
    openaiRaw.output_text ??
    openaiRaw.text ??
    "";
  const claudeResponse =
    claudeRaw.content?.find((entry) => typeof entry?.text === "string")?.text ??
    claudeRaw.text ??
    "";

  if (!openaiResponse) {
    throw new Error(`[handoff_id=${currentId}] Missing OpenAI response`);
  }
  if (!claudeResponse) {
    throw new Error(`[handoff_id=${currentId}] Missing Claude response`);
  }

  return {
    json: {
      ...canonical,
      handoff_id: currentId,
      "Handoff ID": currentId,
      openai_handoff_id: merged.openai_handoff_id,
      claude_handoff_id: merged.claude_handoff_id,
      status: "AI_RESPONSES_READY",
      Status: "AI_RESPONSES_READY",
      openai_response: openaiResponse,
      claude_response: claudeResponse,
      consensus_status: "PENDING",
      deliverable_ref: canonical.deliverable_ref ?? null,
      execution_id: canonical.execution_id ?? null,
      started_at: canonical.started_at ?? null,
      resolved_model_policy: canonical.resolved_model_policy ?? null,
      routing_reason:
        canonical.model_policy_resolution_reason ??
        canonical.selection_reason ??
        canonical.routing_reason ??
        null,
      workflow_version: canonical.workflow_version ?? null,
      retry_count: canonical.retry_count ?? null,
      actual_cost_openai: null,
      actual_cost_claude: null,
      actual_cost_total: null,
      cost_status: "UNAVAILABLE",
      openai_raw: merged.openai_raw,
      openai_model: merged.openai_model ?? null,
      openai_input_tokens: merged.openai_input_tokens ?? null,
      openai_output_tokens: merged.openai_output_tokens ?? null,
      openai_cached_tokens: merged.openai_cached_tokens ?? null,
      openai_response_id: merged.openai_response_id ?? null,
      openai_finish_reason: merged.openai_finish_reason ?? null,
      claude_raw: merged.claude_raw,
      claude_model: merged.claude_model ?? null,
      claude_input_tokens: merged.claude_input_tokens ?? null,
      claude_output_tokens: merged.claude_output_tokens ?? null,
      claude_cache_read_tokens: merged.claude_cache_read_tokens ?? null,
      claude_cache_creation_tokens:
        merged.claude_cache_creation_tokens ?? null,
      claude_response_id: merged.claude_response_id ?? null,
