    source.flagship_output === true ||
    String(source.flagship_output ?? "").toUpperCase() === "TRUE";

  const benchmarkRequired =
    source.benchmark_required === true ||
    String(source.benchmark_required ?? "").toUpperCase() === "TRUE";

  let resolvedPolicy = requestedPolicy;

  if (!["SINGLE", "DUAL", "AUTO"].includes(requestedPolicy)) {
    resolvedPolicy = "AUTO";
  }

  if (resolvedPolicy === "AUTO") {
    const requiresDual =
      ["HIGH", "CRITICAL"].includes(risk) ||
      ["HIGH", "COMPLEX", "VERY_HIGH"].includes(complexity) ||
      ["HIGH", "CRITICAL"].includes(qualityPriority) ||
      flagshipOutput ||
      benchmarkRequired;

    resolvedPolicy = requiresDual ? "DUAL" : "SINGLE";
  }

  return {
    json: {
      ...source,
      requested_model_policy: requestedPolicy,
      resolved_model_policy: resolvedPolicy,
      model_policy_resolution_reason:
        requestedPolicy === "AUTO"
