const normalizeId = (value) =>
  value == null ? "" : String(value).trim();
const sourceItems = $("Choose Single or Dual").all(0);
const expectedIds = sourceItems.map((item) =>
  normalizeId(item.json.handoff_id ?? item.json["Handoff ID"])
);
if (expectedIds.some((id) => id === "")) {
  throw new Error(
    "Phase 5 SINGLE_CLAUDE expected-set carrier: missing Handoff ID"
  );
}
if (new Set(expectedIds).size !== expectedIds.length) {
  throw new Error(
    "Phase 5 SINGLE_CLAUDE expected-set carrier: duplicate Handoff ID"
  );
}
return [{
  json: {
    _p5_control_kind: "EXPECTED_SET_CARRIER",
    provider_branch: "SINGLE_CLAUDE",
    expected_ids: expectedIds
  }
}];

const cloneJson = (value) => {
  if (value == null) return null;
  return JSON.parse(JSON.stringify(value));
};
const inputBoundaryItems = $input.all();
const providerItems = $("Call Claude (Single)").all(0);
if (providerItems.length !== inputBoundaryItems.length) {
  const boundaryItem = inputBoundaryItems[0];
  return [{
    json: {
      _p5_control_kind: "INVALID_PROVIDER_LINEAGE_SNAPSHOT",
      provider_branch: "SINGLE_CLAUDE",
      snapshot_error_code: "DIRECT_UPSTREAM_INPUT_COUNT_MISMATCH",
      direct_upstream_count: providerItems.length,
      input_boundary_count: inputBoundaryItems.length
    },
    pairedItem: cloneJson(boundaryItem?.pairedItem)
  }];
}
return providerItems.map((providerItem, position) => {
  const boundaryItem = inputBoundaryItems[position];
  return {
    json: {
      _p5_control_kind: "PROVIDER_LINEAGE_SNAPSHOT",
      provider_branch: "SINGLE_CLAUDE",
      provider_raw: cloneJson(providerItem.json ?? {}),
      provider_paired_item: cloneJson(providerItem.pairedItem),
      input_boundary_paired_item: cloneJson(boundaryItem?.pairedItem),
      provider_position: position
    },
    pairedItem: cloneJson(boundaryItem?.pairedItem)
  };
});

const normalizeId = (value) =>
  value == null ? "" : String(value).trim();
const items = $input.all();
const sourceItems = $("Choose Single or Dual").all(0);
const carriers = items.filter(
  (item) => item.json._p5_control_kind === "EXPECTED_SET_CARRIER"
);
const expectedIds = sourceItems.map((item) =>
  normalizeId(item.json.handoff_id ?? item.json["Handoff ID"])
);
const providerItems = items.filter(
  (item) => item.json._p5_control_kind !== "EXPECTED_SET_CARRIER"
);
const validationErrors = [];
const resolved = [];

if (carriers.length !== 1) {
  validationErrors.push(
    "expected exactly one carrier; received " + carriers.length
  );
}
if (expectedIds.some((id) => id === "")) {
  validationErrors.push("blank expected Handoff ID");
}
if (new Set(expectedIds).size !== expectedIds.length) {
  validationErrors.push("duplicate expected Handoff ID");
}

for (let position = 0; position < providerItems.length; position++) {
  const item = providerItems[position];
  const snapshot = item.json ?? {};
  const snapshotValid =
    snapshot._p5_control_kind === "PROVIDER_LINEAGE_SNAPSHOT" &&
    snapshot.provider_branch === "SINGLE_CLAUDE" &&
    snapshot.provider_raw != null &&
    Object.prototype.hasOwnProperty.call(snapshot, "provider_paired_item");
  if (!snapshotValid) {
    validationErrors.push(
      "provider output " + position + ": missing valid pre-merge lineage snapshot"
    );
  }
  const providerJson = snapshotValid ? snapshot.provider_raw : {};
  const providerPairedItem = snapshotValid
    ? snapshot.provider_paired_item
    : null;
  const entries = Array.isArray(providerPairedItem)
    ? providerPairedItem
    : providerPairedItem == null
      ? []
      : [providerPairedItem];
  const indexes = new Set();
  let lineageValid = snapshotValid;

  for (const entry of entries) {
    if (!entry || typeof entry !== "object") {
      validationErrors.push(
        "provider output " + position + ": invalid pairedItem entry"
      );
      lineageValid = false;
      continue;
    }
    const input = entry.input ?? 0;
    if (input !== 0) {
      validationErrors.push(
        "provider output " + position + ": invalid pairedItem.input " + input
      );
      lineageValid = false;
    }
    if (!Number.isInteger(entry.item) || entry.item < 0) {
      validationErrors.push(
        "provider output " + position + ": invalid pairedItem.item"
      );
      lineageValid = false;
    } else {
      indexes.add(entry.item);
    }
  }

  if (indexes.size !== 1) {
    validationErrors.push(
      "provider output " + position + ": ambiguous pairedItem lineage"
    );
    lineageValid = false;
  }

  const sourceIndex =
    indexes.size === 1 ? [...indexes][0] : null;
  if (
    sourceIndex !== null &&
    sourceIndex >= sourceItems.length
  ) {
    validationErrors.push(
      "provider output " + position + ": pairedItem index out of range"
    );
    lineageValid = false;
  }

  const recoveredId =
    lineageValid && sourceIndex !== null
      ? normalizeId(
          sourceItems[sourceIndex]?.json?.handoff_id ??
          sourceItems[sourceIndex]?.json?.["Handoff ID"]
        )
      : "";
  if (!recoveredId) {
    validationErrors.push(
      "provider output " + position + ": blank resolved Handoff ID"
    );
  }

  const hasExplicitIdentity =
    Object.prototype.hasOwnProperty.call(providerJson, "handoff_id") ||
    Object.prototype.hasOwnProperty.call(providerJson, "Handoff ID");
  const explicitId = normalizeId(
    providerJson.handoff_id ?? providerJson["Handoff ID"]
  );
  if (hasExplicitIdentity && !explicitId) {
    validationErrors.push(
      "provider output " + position + ": blank explicit Handoff ID"
    );
  }
  if (explicitId && recoveredId && explicitId !== recoveredId) {
    validationErrors.push(
      "provider output " + position + ": explicit Handoff ID mismatch"
    );
  }

  resolved.push({
    providerJson,
    providerPairedItem,
    sourceIndex,
    recoveredId
  });
}

const actualIds = resolved.map((entry) => entry.recoveredId);
const expectedSet = new Set(expectedIds);
const actualSet = new Set(actualIds);
const safe =
  validationErrors.length === 0 &&
  expectedIds.every(Boolean) &&
  actualIds.every(Boolean) &&
  expectedSet.size === expectedIds.length &&
  actualSet.size === actualIds.length &&
  actualIds.length === expectedIds.length &&
  expectedIds.every((id) => actualSet.has(id)) &&
  actualIds.every((id) => expectedSet.has(id));

if (safe) {
  return resolved.map((entry) => ({
    json: {
      _p5_control_kind: "VALIDATED_PROVIDER_OUTPUT",
      provider_branch: "SINGLE_CLAUDE",
      handoff_id: entry.recoveredId,
      "Handoff ID": entry.recoveredId,
      safety_approved: true,
      provider_raw: entry.providerJson,
      provider_paired_item: entry.providerPairedItem,
      source_index: entry.sourceIndex
    },
    pairedItem: entry.providerPairedItem
  }));
}

const detail =
  "Phase 5 SINGLE_CLAUDE provider set mismatch; expected=[" +
  expectedIds.join(",") +
  "], actual=[" +
  actualIds.join(",") +
  "], validation=[" +
  validationErrors.join("; ") +
  "]";

const safetyIds = [...new Set(expectedIds.filter(Boolean))];
const outputIds = safetyIds.length > 0 ? safetyIds : [""];
return outputIds.map((handoffId) => ({
  json: {
    handoff_id: handoffId,
    "Handoff ID": handoffId,
    safety_approved: false,
    safety_error_code: "SINGLE_CLAUDE_OUTPUT_CARDINALITY_MISMATCH",
    safety_error_message: detail
  }
}));

const normalizeId = (value) => value == null ? "" : String(value).trim();
const sourceItems = $("Choose Single or Dual").all(0);
return $input.all().map((item) => {
  const validated = item.json ?? {};
  if (validated._p5_control_kind !== "VALIDATED_PROVIDER_OUTPUT" ||
      validated.provider_branch !== "SINGLE_CLAUDE" ||
      validated.safety_approved !== true ||
      validated.provider_raw == null ||
      !Number.isInteger(validated.source_index)) {
    throw new Error("Single Claude provider envelope: unvalidated provider output");
  }
  const source = sourceItems[validated.source_index]?.json;
  const handoffId = normalizeId(source?.handoff_id ?? source?.["Handoff ID"]);
  if (!handoffId) throw new Error("Single Claude provider envelope: source Handoff ID missing");
  return {
    json: {
      _p5_control_kind: "PROVIDER_OUTPUT",
      handoff_id: handoffId,
      "Handoff ID": handoffId,
      claude_handoff_id: handoffId,
      claude_raw: validated.provider_raw,
      _p5_source_index: validated.source_index
    },
    pairedItem: validated.provider_paired_item
  };
});

const normalizeId = (value) => value == null ? "" : String(value).trim();
const sourceItems = $("Choose Single or Dual").all(0);
const nonNegativeIntegerOrNull = (value) => Number.isInteger(value) && value >= 0 ? value : null;
const results = $input.all().map((item) => {
  const envelope = item.json ?? {};
  const response = envelope.claude_raw ?? {};
  const sourceIndex = envelope._p5_source_index;
  if (!Number.isInteger(sourceIndex) || sourceIndex < 0 || sourceIndex >= sourceItems.length) {
    throw new Error("Build Claude Result (Single): source index out of bounds");
  }
  const source = sourceItems[sourceIndex]?.json;
  const handoffId = normalizeId(source?.handoff_id ?? source?.["Handoff ID"]);
  if (!handoffId) throw new Error("Build Claude Result (Single): source Handoff ID missing");
  const content = Array.isArray(response.content) ? response.content : [];
  const messageText = content.filter(x => x?.type === "text" && typeof x.text === "string").map(x => x.text).join("\n");
  const usage = response.usage && typeof response.usage === "object" ? response.usage : {};
  const inputTokens = nonNegativeIntegerOrNull(usage.input_tokens);
  const outputTokens = nonNegativeIntegerOrNull(usage.output_tokens);
  const cacheRead = nonNegativeIntegerOrNull(usage.cache_read_input_tokens);
  const cacheCreation = nonNegativeIntegerOrNull(usage.cache_creation_input_tokens);
  const actualCostClaude = inputTokens !== null && outputTokens !== null
    ? (inputTokens * 3.0 + outputTokens * 15.0) / 1000000
    : null;
  const stopReason = response.stop_reason == null ? null : String(response.stop_reason);
  const completed = ["end_turn", "stop_sequence"].includes(stopReason);
  const completedAt = new Date().toISOString();
  const startedMs = Date.parse(source.started_at ?? "");
  const completedMs = Date.parse(completedAt);
  return {
    json: {
      ...source,
      handoff_id: handoffId,
      "Handoff ID": handoffId,
      status: completed ? "COMPLETED" : "FAILED",
      Status: completed ? "COMPLETED" : "FAILED",
      ...(completed ? {} : {
        error_category: "PROVIDER_RESPONSE",
        error_code: "CLAUDE_RESPONSE_NOT_COMPLETED",
        error_message: "Anthropic returned stop_reason " + (stopReason ?? "UNAVAILABLE")
      }),
      selected_ai: "CLAUDE",
      consensus_status: "SINGLE_MODEL",
      final_answer: messageText,
      completed_at: completedAt,
      processing_time_ms: Number.isFinite(startedMs) ? Math.max(0, completedMs - startedMs) : null,
      processing_version: source.processing_version ?? "v1.0",
      execution_id: source.execution_id ?? null,
      started_at: source.started_at ?? null,
      resolved_model_policy: source.resolved_model_policy ?? null,
      routing_reason: source.model_policy_resolution_reason ?? source.selection_reason ?? source.routing_reason ?? null,
      workflow_version: source.workflow_version ?? null,
      retry_count: source.retry_count ?? null,
      deliverable_ref: source.deliverable_ref ?? null,
      model_call_count: 1,
      actual_cost_openai: null,
      actual_cost_claude: actualCostClaude,
      actual_cost_total: actualCostClaude,
      cost_status: actualCostClaude === null ? "UNAVAILABLE" : "CALCULATED_CONSERVATIVE",
      claude_raw: response,
      claude_model: response.model == null ? null : String(response.model),
      claude_input_tokens: inputTokens,
      claude_output_tokens: outputTokens,
      claude_cache_read_tokens: cacheRead,
      claude_cache_creation_tokens: cacheCreation,
      claude_response_id: response.id == null ? null : String(response.id),
      claude_stop_reason: stopReason
    },
    pairedItem: item.pairedItem
  };
});
const resultIds = results.map(i => i.json.handoff_id);
if (new Set(resultIds).size !== resultIds.length) throw new Error("Build Claude Result (Single): duplicate Handoff ID");
return results;
